output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartInSingleFileShelfAisle": {
          "and": [
            "hasCart",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileShelfAisle"
    }
  },
  {
    "id": "no_enter_restricted_aisle_with_cart",
    "text": "An agent must not move into a narrow shelf-adjacent aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "restrictedShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {
        "enterRestrictedShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "restrictedShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterRestrictedShelfAisleWithCart"
    }
  },
  {
    "id": "must_park_before_pedestrian_aisle_task",
    "text": "For a trip that requires accessing a pedestrian-only shelf aisle, the agent is obliged to park the cart in a wide open bay.",
    "abstraction": {
      "state_properties": {
        "wideOpenBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCartInWideOpenBay": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "wideOpenBay"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "parkCartInWideOpenBay"
    }
  },
  {
    "id": "park_only_in_wide_open_bay",
    "text": "Carts may only be set down in wide open bays, not in narrow aisles or beside shelves.",
    "abstraction": {
      "state_properties": {
        "wideOpenBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDrop",
          {
            "not": "wideOpenBay"
          }
        ]
      }
    }
  },
  {
    "id": "no_item_interact_with_cart_in_pedestrian_aisle",
    "text": "Item interactions in pedestrian-only shelf aisles must not be performed while holding a cart.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pedestrianOnlyShelfAisle",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_pedestrian_item",
    "text": "After collecting an item from a pedestrian-only shelf aisle without the cart, the agent must eventually retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "collectFromPedestrianAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "pedestrianOnlyShelfAisle"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collectFromPedestrianAisle",
      "discharge": "hasCart"
    }
  },
  {
    "id": "pickup_after_return_to_open_bay",
    "text": "When returning from a pedestrian-only aisle to a wide open bay without the cart, the agent must pick the cart back up there.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideOpenBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "returnFromPedestrianAisleToOpenBay": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              "pedestrianOnlyShelfAisle"
            ]
          },
          "post": "wideOpenBay"
        },
        "pickupCartInOpenBay": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "wideOpenBay"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnFromPedestrianAisleToOpenBay",
      "discharge": "pickupCartInOpenBay"
    }
  },
  {
    "id": "return_to_main_corridor_after_pedestrian_aisle",
    "text": "Pedestrian-only shelf aisles should be used as temporary browsing aisles, so after entering one the agent must return to a wide open main corridor.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideOpenMainCorridor": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "enterPedestrianOnlyAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "pedestrianOnlyShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterPedestrianOnlyAisleOnFoot",
      "discharge": "wideOpenMainCorridor"
    }
  }
]
